local type, error, pcall, tonumber, ipairs, pairs = type, error, pcall, tonumber, ipairs, pairs
local max, format, concat = math.max, string.format, table.concat

local HIGH = 4294967296
local MEM_COMMIT, MEM_PRIVATE, PAGE_READWRITE = 0x1000, 0x20000, 4

-- Windows functions ----------------------------------------------------------------

-- The region record is MEMORY_BASIC_INFORMATION with each 64-bit field read as
-- two 32-bit halves, and the cell turns a pointer into two halves through one
-- union (one base, so compiled code sees the store): neither allocates when read.
-- The region record is also this file's sentinel: once it exists, every
-- declaration below exists too.
local PREFIX = 'bingus_memory1_'
local SENTINEL = 'bingus_memory1_region'
local DECLARATIONS = [[
    typedef struct bingus_memory1_region {
        uint32_t base_low, base_high, allocation_base_low, allocation_base_high;
        uint32_t allocation_protection; uint16_t partition, reserved;
        uint32_t size_low, size_high, state, protection, type, padding;
    } bingus_memory1_region;
    typedef union bingus_memory1_cell {
        const void *pointer;
        struct { uint32_t low, high; };
    } bingus_memory1_cell;
    void *bingus_memory1_GetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
    uint32_t bingus_memory1_GetModuleFileNameW(void *module, uint16_t *path, uint32_t capacity) __asm__("GetModuleFileNameW");
    void *bingus_memory1_GetCurrentProcess(void) __asm__("GetCurrentProcess");
    int bingus_memory1_ReadProcessMemory(void *process, const void *address, void *buffer, size_t size,
                                         size_t *done) __asm__("ReadProcessMemory");
    uint32_t bingus_memory1_VirtualQuery(uint64_t address, bingus_memory1_region *region, size_t size) __asm__("VirtualQuery");
    int bingus_memory1_QueryPerformanceCounter(uint32_t *count) __asm__("QueryPerformanceCounter");
    int bingus_memory1_QueryPerformanceFrequency(uint32_t *frequency) __asm__("QueryPerformanceFrequency");
    void *bingus_memory1_CreateFileW(const uint16_t *path, uint32_t access, uint32_t share, void *security,
                                     uint32_t disposition, uint32_t flags, void *template_file) __asm__("CreateFileW");
    int bingus_memory1_ReadFile(void *file, void *buffer, uint32_t size, uint32_t *done, void *overlapped) __asm__("ReadFile");
    int bingus_memory1_CloseHandle(void *handle) __asm__("CloseHandle");
    int32_t bingus_memory1_BCryptOpenAlgorithmProvider(void **algorithm, const uint16_t *name, const uint16_t *provider,
                                                       uint32_t flags) __asm__("BCryptOpenAlgorithmProvider");
    int32_t bingus_memory1_BCryptCloseAlgorithmProvider(void *algorithm, uint32_t flags) __asm__("BCryptCloseAlgorithmProvider");
    int32_t bingus_memory1_BCryptCreateHash(void *algorithm, void **hash, void *object, uint32_t object_size,
                                            const void *secret, uint32_t secret_size, uint32_t flags) __asm__("BCryptCreateHash");
    int32_t bingus_memory1_BCryptHashData(void *hash, const void *data, uint32_t size, uint32_t flags) __asm__("BCryptHashData");
    int32_t bingus_memory1_BCryptFinishHash(void *hash, void *digest, uint32_t size, uint32_t flags) __asm__("BCryptFinishHash");
    int32_t bingus_memory1_BCryptDestroyHash(void *hash) __asm__("BCryptDestroyHash");
]]
local FUNCTIONS = {
    kernel32 = {'GetModuleHandleA', 'GetModuleFileNameW', 'GetCurrentProcess', 'ReadProcessMemory', 'VirtualQuery',
                'QueryPerformanceCounter', 'QueryPerformanceFrequency', 'CreateFileW', 'ReadFile', 'CloseHandle'},
    bcrypt = {'BCryptOpenAlgorithmProvider', 'BCryptCloseAlgorithmProvider', 'BCryptCreateHash',
              'BCryptHashData', 'BCryptFinishHash', 'BCryptDestroyHash'},
}

local bound, ticks_per_second
-- {ffi, kernel32, bcrypt}, each library table holding the functions above under
-- their Windows names. Declared at most once per version in the whole game.
local function bind()
    if bound then return bound end
    local ffi = require('ffi')
    if not ffi.abi('64bit') then error('Windows x64 is required', 0) end
    if not pcall(ffi.typeof, SENTINEL) then ffi.cdef(DECLARATIONS) end
    local result = {ffi = ffi}
    for library, names in pairs(FUNCTIONS) do
        local loaded, functions = ffi.load(library), {}
        for _, name in ipairs(names) do functions[name] = loaded[PREFIX .. name] end
        result[library] = functions
    end
    local frequency = ffi.new('uint32_t[2]')
    if result.kernel32.QueryPerformanceFrequency(frequency) == 0 then error('performance counter unavailable', 0) end
    ticks_per_second = frequency[0] + frequency[1] * HIGH
    bound = result
    return bound
end

-- Module files ---------------------------------------------------------------------

-- SHA-256 (uppercase hex) of the file at path (a UTF-16 string buffer).
local function sha256(windows, path)
    local ffi, kernel, bcrypt = windows.ffi, windows.kernel32, windows.bcrypt
    local file = kernel.CreateFileW(path, 0x80000000, 7, nil, 3, 0x08000000, nil)
    if file == ffi.cast('void *', -1) then error('cannot read the module file', 0) end
    local algorithm, hash = ffi.new('void *[1]'), ffi.new('void *[1]')
    local ok, result = pcall(function()
        local id = ffi.new('uint16_t[7]', {83, 72, 65, 50, 53, 54, 0})  -- "SHA256"
        if bcrypt.BCryptOpenAlgorithmProvider(algorithm, id, nil, 0) ~= 0 then error('SHA-256 unavailable', 0) end
        if bcrypt.BCryptCreateHash(algorithm[0], hash, nil, 0, nil, 0, 0) ~= 0 then
            error('SHA-256 unavailable', 0)
        end
        local buffer, count = ffi.new('uint8_t[1048576]'), ffi.new('uint32_t[1]')
        while true do
            if kernel.ReadFile(file, buffer, 1048576, count, nil) == 0 then error('module file read failed', 0) end
            if count[0] == 0 then break end
            if bcrypt.BCryptHashData(hash[0], buffer, count[0], 0) ~= 0 then error('SHA-256 failed', 0) end
        end
        local digest, hex = ffi.new('uint8_t[32]'), {}
        if bcrypt.BCryptFinishHash(hash[0], digest, 32, 0) ~= 0 then error('SHA-256 failed', 0) end
        for i = 0, 31 do hex[i + 1] = format('%02X', digest[i]) end
        return concat(hex)
    end)
    if hash[0] ~= nil then bcrypt.BCryptDestroyHash(hash[0]) end
    if algorithm[0] ~= nil then bcrypt.BCryptCloseAlgorithmProvider(algorithm[0], 0) end
    kernel.CloseHandle(file)
    if not ok then error(result, 0) end
    return result
end

-- The SHA-256 of a loaded module's file, read once per session for every mod:
-- kept in the shared table by file path.
local function module_hash(runtime, windows, module)
    local ffi = windows.ffi
    local path = ffi.new('uint16_t[32768]')
    local length = windows.kernel32.GetModuleFileNameW(module, path, 32768)
    if length == 0 or length >= 32768 then error('module file name unavailable', 0) end
    local shared = runtime.shared()
    local key = 'sha256:' .. ffi.string(path, length * 2)
    local cached = shared.hashes[key]
    if cached then return cached end
    local hex = sha256(windows, path)
    shared.hash_reads = shared.hash_reads + 1
    shared.hashes[key] = hex
    return hex
end

-- The api --------------------------------------------------------------------------

function memory.new(runtime)
    if type(runtime) ~= 'table' or type(runtime.shared) ~= 'function' then
        error('bingus_memory.lua: new(runtime) needs the table bingus_runtime.lua returns', 2)
    end
    runtime.shared()
    local windows = bind()
    local ffi, kernel = windows.ffi, windows.kernel32
    local read_memory, query, query_counter = kernel.ReadProcessMemory, kernel.VirtualQuery,
        kernel.QueryPerformanceCounter
    local process = kernel.GetCurrentProcess()
    -- ReadProcessMemory reports its count as a 64-bit size: it is read back as two
    -- 32-bit words, because reading the 64-bit value boxes a new cdata in
    -- interpreted code. Only the call writes this buffer.
    local done = ffi.new('size_t[1]')
    local done32 = ffi.cast('uint32_t *', done)
    local region, region_size = ffi.new(SENTINEL), ffi.sizeof(SENTINEL)
    local cell, counter = ffi.new('bingus_memory1_cell'), ffi.new('uint32_t[2]')
    local scratch_size = 256
    local scratch = ffi.new('uint8_t[?]', scratch_size)
    local ticks = ticks_per_second
    local api = {queries = 0, windows = windows}

    -- A pointer, number or integer cdata as a number, without allocating: a
    -- pointer passes through the cell. Exact below 2^53 (user-mode addresses
    -- end at 2^47).
    local function address_of(address)
        if type(address) == 'number' then return address end
        if type(address) == 'cdata' then
            local integer = tonumber(address)
            if integer then return integer end
        end
        cell.pointer = address
        return cell.low + cell.high * HIGH
    end

    function api.module(name)
        local handle = kernel.GetModuleHandleA(name)
        if handle == nil then return nil end
        return ffi.cast('uint8_t *', handle)
    end

    -- The bytes at address as a string, or nil when they cannot all be read.
    -- Allocates only the returned string.
    function api.read(address, size)
        if size > scratch_size then
            scratch_size = max(size, scratch_size * 2)
            scratch = ffi.new('uint8_t[?]', scratch_size)
        end
        if read_memory(process, address, scratch, size, done) == 0 or done32[0] ~= size then
            return nil
        end
        return ffi.string(scratch, size)
    end

    -- Into a buffer the caller keeps: no allocation at all.
    function api.read_into(address, size, buffer)
        return read_memory(process, address, buffer, size, done) ~= 0 and done32[0] == size
    end

    -- The user-mode pointer stored little-endian at bytes[offset+1 .. offset+8].
    function api.pointer(bytes, offset)
        offset = offset or 0
        if type(bytes) ~= 'string' or offset < 0 or offset + 8 > #bytes then return nil end
        local b1, b2, b3, b4, b5, b6, b7, b8 = bytes:byte(offset + 1, offset + 8)
        if b7 ~= 0 or b8 ~= 0 then return nil end
        local value = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216 + (b5 + b6 * 256) * HIGH
        if value < 0x10000 or value >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', value)
    end

    api.address = address_of

    function api.distance(first, second)
        return address_of(first) - address_of(second)
    end

    -- True when [address, address + size) is committed private read-write memory:
    -- never code, read-only, guard or module image pages. One VirtualQuery per
    -- region, each answered in the region record (no allocation).
    function api.writable_data(address, size)
        if type(size) ~= 'number' or size <= 0 then return false end
        local cursor = address_of(address)
        local finish = cursor + size
        while cursor < finish do
            api.queries = api.queries + 1
            if query(cursor, region, region_size) ~= region_size then return false end
            if region.state ~= MEM_COMMIT or region.type ~= MEM_PRIVATE or region.protection ~= PAGE_READWRITE then
                return false
            end
            local region_end = region.base_low + region.base_high * HIGH + region.size_low + region.size_high * HIGH
            if region_end <= cursor then return false end
            cursor = region_end
        end
        return true
    end

    -- Seconds since an arbitrary start (boot), from the performance counter read
    -- as two 32-bit halves into a reused buffer; the frequency is read once.
    function api.time()
        query_counter(counter)
        return (counter[0] + counter[1] * HIGH) / ticks
    end

    function api.module_hash(module)
        return module_hash(runtime, windows, module)
    end

    -- build: {exe_sha256, game_sha256}. true, or false and why.
    function api.verify_build(build)
        local exe, game = api.module(nil), api.module('game.dll')
        if not exe or not game then return false, 'game modules unavailable' end
        if api.module_hash(exe) ~= build.exe_sha256 or api.module_hash(game) ~= build.game_sha256 then
            return false, 'unsupported game build'
        end
        return true
    end

    return api
end

return memory
end)()
local Mod = (function()
-- Sound Systems Rebalanced for Helldivers 2 Steam build 26088801.
-- The Super Destroyer's rooms set the Wwise state environment_shiphub_room as you walk through them, and the
-- war-table area (shiphub_view) lowers the music bus by 6 dB. Nothing resets that state when you leave the ship,
-- so a mission's music played 6 dB louder when you deployed from anywhere but the war table, most often when
-- joining a mission already in progress. This mod sets shiphub_view whenever a mission starts, so every mission
-- plays its music at the war-table level that most players hear. In missions that state changes only the music
-- bus; back on the ship its own triggers set the room again as the player walks between rooms (as after any
-- mission started from the war table).
-- Cost: every 0.25 s of game time one 4-byte read of the game state ([game.dll+0x2CE1508] + 0xAC29C); the frames
-- between do no system call. Entering a mission (state 6, preparing a mission, or 4, mission) calls the engine's
-- stingray.Wwise.set_state once and writes one log line. Nothing is written to game memory. A second deployed copy
-- does nothing.
local Mod = {VERSION = '1.0'}

local ffi = require('ffi')

Mod.EXE_SHA256 = '0ACC07DEBE04714AE04281E1A66BD2EB9D3D85232953E32A93C8A3DD0874EABE'
Mod.GAME_SHA256 = '6D1D4D3BC6FC84801D9F8F1B310E13A603D07409F3D9495D74B42E1D0BB1C08F'

-- Build 26088801: the game object's static pointer and its game state (1 splash, 2 title, 5 preparing the ship,
-- 3 ship, 6 preparing a mission, 4 mission; also read by Hellpod Drop Hold). Tests pass their own layout.
Mod.LAYOUT = {game_rva = 0x2CE1508, state_offset = 0xAC29C}
Mod.MISSION_STATES = {[6] = true, [4] = true}
Mod.MAX_STATE = 64          -- a larger value means the game object moved: resolve its pointer again
Mod.CHECK_SECONDS = 0.25    -- game time between two reads of the game state
Mod.FALLBACK_DT = 1 / 60    -- frame time when the update chain passes no number
-- Wwise names (FNV-1 hashed by Wwise): the state group 0xEC643124 and its value 0x08EEC31C.
Mod.GROUP, Mod.ROOM = 'environment_shiphub_room', 'shiphub_view'

-- Raises reason without a source position, so the log line reads as the reason.
local function need(value, reason)
    if not value then error(reason, 0) end
    return value
end

-- The watcher. api: bingus_memory.lua's api (read_into only); game: game.dll's base as uint8_t *; set_state(group,
-- value): sets a global Wwise state by name; note(line): the log; state: the status table (missions, status).
function Mod.new(api, game, set_state, note, state, layout)
    layout = layout or Mod.LAYOUT
    local self = {}
    local slot = game + layout.game_rva
    local pointer_buffer = ffi.new('uint64_t[1]')
    local state_buffer = ffi.new('uint32_t[1]')
    local state_address = nil
    local elapsed, in_mission = Mod.CHECK_SECONDS, false -- the first frame reads at once

    local function resolve()
        state_address = nil
        if not api.read_into(slot, 8, pointer_buffer) then return false end
        local object = tonumber(pointer_buffer[0])
        if object < 0x10000 or object >= 0x800000000000 then return false end
        state_address = ffi.cast('uint8_t *', object + layout.state_offset)
        return true
    end

    -- The game state, or nil while the game object is missing or the read fails.
    local function game_state()
        if state_address == nil and not resolve() then return nil end
        if not api.read_into(state_address, 4, state_buffer) then
            state_address = nil
            return nil
        end
        local value = state_buffer[0]
        if value > Mod.MAX_STATE then
            state_address = nil
            return nil
        end
        return value
    end

    local function enter_mission(value)
        if set_state(Mod.GROUP, Mod.ROOM) == false then return end -- port: the native path refused (logged)
        state.missions = state.missions + 1
        state.status = 'held mission music at the war-table level ' .. state.missions .. ' time(s)'
        note(string.format('Mission start (game state %d): music held at the war-table level (%s = %s).', value,
            Mod.GROUP, Mod.ROOM))
    end

    function self.step(dt)
        elapsed = elapsed + (tonumber(dt) or Mod.FALLBACK_DT)
        if elapsed < Mod.CHECK_SECONDS then return end
        elapsed = 0
        local value = game_state()
        if value == nil then return end
        local mission = Mod.MISSION_STATES[value] == true
        if mission and not in_mission then enter_mission(value) end
        in_mission = mission
    end
    -- The guard calls step under pcall, so a trace started at its entry aborts where it returns ("NYI: return to
    -- lower frame") and retries whenever LuaJIT's 64 penalty slots have evicted it. Run step interpreted (about 13
    -- bytecodes on an idle frame, as before: it never compiled); the read path it calls still compiles.
    if type(jit) == 'table' and type(jit.off) == 'function' then jit.off(self.step) end

    -- An update below raised: start fresh (the next mission state sets the room again; setting it twice is
    -- harmless).
    function self.pause()
        elapsed, in_mission, state_address = Mod.CHECK_SECONDS, false, nil
    end

    function self.stopped(reason)
        state.status = 'stopped: ' .. tostring(reason)
        note(string.format('Stopped (%s) after %d mission(s).', tostring(reason), state.missions))
    end

    return self
end

-- The engine's Wwise Lua binding (stingray.Wwise.set_state), or nil.
function Mod.engine_set_state(globals)
    local ok, set_state = pcall(function()
        local stingray = rawget(globals or _G, 'stingray')
        return stingray and stingray.Wwise and stingray.Wwise.set_state
    end)
    if ok and type(set_state) == 'function' then return set_state end
    return nil
end

-- Port to Steam build 26088801, the one non-data edit (native-work/megapack-port/SoundSystemsRebalanced/NOTES.md):
-- the engine no longer registers stingray.Wwise.set_state. That binding called the Wwise plugin's exported
-- AK::SoundEngine::SetState(const char *, const char *), which the already-loaded plugin still exports. No DLL is
-- loaded: the plugin must already be in the process. Before every call the export must resolve at its expected RVA
-- and its first bytes, read with ReadProcessMemory (api.read: the page may be unreadable until the game first runs
-- it), must equal the expected prologue; otherwise nothing is called and one line is logged.
Mod.WWISE = {
    module = 'wwise_pluginw64_release.dll',
    export = '?SetState@SoundEngine@AK@@YA?AW4AKRESULT@@PEBD0@Z',
    rva = 0xDA120, -- the current plugin file's export table
    -- The export's first 31 bytes (whole, position-independent instructions) in the build-25480438 plugin, built from
    -- the same Wwise SDK 2024.1.9.8920 library. The current file is encrypted on disk: a live match is the check.
    prologue = '\064\083\069\051\201\076\139\218\072\139\217\072\133\201\117\005\069\139\209\235\074\068\015\182\001'
        .. '\065\186\197\157\028\129',
    success = 1, -- AK_Success
}

-- A set_state(group, value) calling the plugin's SetState after those checks (true when Wwise accepted the state,
-- false when it was refused or not called), or nil when the plugin is not loaded. get_proc(module, name) is for
-- tests; by default kernel32's GetProcAddress under a private FFI name.
function Mod.native_set_state(api, note, get_proc)
    local W = Mod.WWISE
    if not api.module(W.module) then return nil end
    get_proc = get_proc or function(module, name)
        if not pcall(ffi.typeof, 'struct ssr_port1_sentinel') then
            ffi.cdef([[struct ssr_port1_sentinel { int unused; };
                void *ssr_port1_GetProcAddress(void *module, const char *name) __asm__("GetProcAddress");]])
        end
        local address = ffi.load('kernel32').ssr_port1_GetProcAddress(module, name)
        if address == nil then return nil end
        return address
    end
    return function(group, value)
        local module = api.module(W.module)
        local address = module and get_proc(module, W.export)
        local why
        if not module then why = 'the Wwise plugin is not loaded'
        elseif not address then why = 'the SetState export did not resolve'
        elseif api.distance(address, module) ~= W.rva then why = 'the SetState export is not at its expected RVA'
        else
            local bytes = api.read(address, #W.prologue)
            if bytes == nil then why = 'the SetState code is unreadable'
            elseif bytes ~= W.prologue then why = 'the SetState code differs from the expected prologue' end
        end
        if why then
            note('Wwise state not set: ' .. why .. '; nothing was called.')
            return false
        end
        local result = ffi.cast('int32_t (*)(const char *, const char *)', address)(group, value)
        if result ~= W.success then
            note('Wwise state not set: SetState returned ' .. tostring(result) .. '.')
            return false
        end
        return true
    end
end

local function log_writer(loader)
    local file
    if type(loader) == 'table' and type(loader.open_log) == 'function' then
        pcall(function() file = loader.open_log('SoundSystemsRebalanced.log') end)
    end
    return function(line)
        print('[SoundSystemsRebalanced] ' .. line)
        if file then pcall(function() file:write(line .. '\n'); file:flush() end) end
    end
end

-- Installs the mod. runtime: bingus_runtime.lua; api: bingus_memory.lua's api. options: env (the table holding
-- update and shutdown, default _G), loader (default the global Bingus Shared Loader), set_state (default the
-- engine's stingray.Wwise.set_state), layout. Returns the status table.
function Mod.install(runtime, api, options)
    options = options or {}
    local env = options.env or _G
    local loader = options.loader or rawget(_G, 'CowboyBingusModLoader')
    local state = {version = Mod.VERSION, status = 'starting', missions = 0}
    rawset(env, 'SoundSystemsRebalanced', state)
    local note = log_writer(loader)
    local ok, instance = pcall(function()
        need(type(loader) == 'table' and loader.api == 1 and type(loader.open_log) == 'function',
            'Bingus Shared Loader with API 1 required')
        local built, why = api.verify_build({exe_sha256 = Mod.EXE_SHA256, game_sha256 = Mod.GAME_SHA256})
        need(built, why == 'unsupported game build' and 'unsupported game build (needs Steam build 26088801)'
            or tostring(why))
        local game = need(api.module('game.dll'), 'game.dll not loaded')
        local set_state = need(options.set_state or Mod.engine_set_state(env) or Mod.native_set_state(api, note),
            "the engine's stingray.Wwise.set_state is unavailable and the Wwise plugin is not loaded")
        return Mod.new(api, game, set_state, note, state, options.layout)
    end)
    if not ok then
        state.status = 'disabled: ' .. tostring(instance)
        note('Sound Systems Rebalanced v' .. Mod.VERSION .. ' disabled: ' .. tostring(instance))
        return state
    end
    runtime.guard({name = 'SoundSystemsRebalanced', step = instance.step, stop = instance.stopped, pause = instance.pause,
                   log = note, env = env}).install()
    state.status = 'watching for mission starts'
    note('Sound Systems Rebalanced v' .. Mod.VERSION .. ': watching for mission starts.')
    return state
end

return Mod
end)()
Mod.install(bingus_runtime, bingus_memory.new(bingus_runtime))
